---| "joint.distance.local_anchor_a" # Vec2 - Anchor on body A, relative to its origin (px).
---| "joint.distance.local_anchor_b" # Vec2 - Anchor on body B, relative to its origin (px).
---| "joint.distance.length" # number - Rest distance between the anchors (px).
---| "joint.distance.enable_spring" # boolean - Make the joint springy instead of rigid.
---| "joint.distance.hertz" # number - Spring stiffness as an oscillation frequency (Hz); 0 = no spring.
---| "joint.distance.damping_ratio" # number - Spring damping: 0 bounces forever, 1 settles without overshoot.
---| "joint.distance.enable_limit" # boolean - Clamp the joint's travel to the lower / upper limits.
---| "joint.distance.min_length" # number - Shortest the joint may get (px; with the limit on).
---| "joint.distance.max_length" # number - Longest the joint may get (px; with the limit on).
---| "joint.distance.enable_motor" # boolean - Drive the joint at Motor Speed, up to the maximum force / torque.
---| "joint.distance.max_motor_force" # number - Strongest push the motor applies (pixel-scale bodies are heavy: mass ~ area in px²).
---| "joint.distance.motor_speed" # number - Speed the motor lengthens (+) or shortens (-) the joint (px/s).
---| "joint.distance.collide_connected" # boolean - Let the two connected bodies collide with each other.
---| "joint.motor.linear_offset" # Vec2 - Where body B is driven to, relative to body A (px).
---| "joint.motor.angular_offset" # number - Angle body B is driven to, relative to body A (degrees).
---| "joint.motor.max_force" # number - Strongest pull towards the offset (pixel-scale bodies are heavy).
---| "joint.motor.max_torque" # number - Strongest twist towards the angle (pixel-scale bodies are heavy).
---| "joint.motor.correction_factor" # number - How quickly position errors are corrected (0-1).
---| "joint.motor.collide_connected" # boolean - Let the two connected bodies collide with each other.
---| "joint.mouse.target" # Vec2 - World point the body is pulled to (px).
---| "joint.mouse.hertz" # number - Stiffness of the pull (Hz).
---| "joint.mouse.damping_ratio" # number - Damping of the pull: 1 = no overshoot.
---| "joint.mouse.max_force" # number - Strongest pull applied.
---| "joint.mouse.collide_connected" # boolean - Let the two connected bodies collide with each other.
---| "joint.prismatic.local_anchor_a" # Vec2 - Anchor on body A, relative to its origin (px).
---| "joint.prismatic.local_anchor_b" # Vec2 - Anchor on body B, relative to its origin (px).
---| "joint.prismatic.local_axis_a" # Vec2 - Direction body B slides along, in body A's space.
---| "joint.prismatic.reference_angle" # number - Body B's angle relative to body A that counts as zero (degrees).
---| "joint.prismatic.target_translation" # number - Position the spring pulls to along the axis (px).
---| "joint.prismatic.enable_spring" # boolean - Make the joint springy instead of rigid.
---| "joint.prismatic.hertz" # number - Spring stiffness as an oscillation frequency (Hz); 0 = no spring.
---| "joint.prismatic.damping_ratio" # number - Spring damping: 0 bounces forever, 1 settles without overshoot.
---| "joint.prismatic.enable_limit" # boolean - Clamp the joint's travel to the lower / upper limits.
---| "joint.prismatic.lower_translation" # number - Furthest back along the axis (px; with the limit on).
---| "joint.prismatic.upper_translation" # number - Furthest forward along the axis (px; with the limit on).
---| "joint.prismatic.enable_motor" # boolean - Drive the joint at Motor Speed, up to the maximum force / torque.
---| "joint.prismatic.max_motor_force" # number - Strongest push the motor applies (pixel-scale bodies are heavy).
---| "joint.prismatic.motor_speed" # number - Sliding speed the motor drives (px/s).
---| "joint.prismatic.collide_connected" # boolean - Let the two connected bodies collide with each other.
---| "joint.revolute.local_anchor_a" # Vec2 - Anchor on body A, relative to its origin (px).
---| "joint.revolute.local_anchor_b" # Vec2 - Anchor on body B, relative to its origin (px).
---| "joint.revolute.reference_angle" # number - Body B's angle relative to body A that counts as zero (degrees).
---| "joint.revolute.target_angle" # number - Angle the spring pulls to (degrees).
---| "joint.revolute.enable_spring" # boolean - Make the joint springy instead of rigid.
---| "joint.revolute.hertz" # number - Spring stiffness as an oscillation frequency (Hz); 0 = no spring.
---| "joint.revolute.damping_ratio" # number - Spring damping: 0 bounces forever, 1 settles without overshoot.
---| "joint.revolute.enable_limit" # boolean - Clamp the joint's travel to the lower / upper limits.
---| "joint.revolute.lower_angle" # number - Smallest angle (degrees; with the limit on).
---| "joint.revolute.upper_angle" # number - Largest angle (degrees; with the limit on).
---| "joint.revolute.enable_motor" # boolean - Drive the joint at Motor Speed, up to the maximum force / torque.
---| "joint.revolute.max_motor_torque" # number - Strongest twist the motor applies (pixel-scale bodies are heavy).
---| "joint.revolute.motor_speed" # number - Spin speed the motor drives (radians/s).
---| "joint.revolute.collide_connected" # boolean - Let the two connected bodies collide with each other.
---| "joint.weld.local_anchor_a" # Vec2 - Anchor on body A, relative to its origin (px).
---| "joint.weld.local_anchor_b" # Vec2 - Anchor on body B, relative to its origin (px).
---| "joint.weld.reference_angle" # number - Body B's angle relative to body A that counts as zero (degrees).
---| "joint.weld.linear_hertz" # number - Positional softness (Hz); 0 = rigid.
---| "joint.weld.angular_hertz" # number - Angular softness (Hz); 0 = rigid.
---| "joint.weld.linear_damping_ratio" # number - Damping of the positional softness.
---| "joint.weld.angular_damping_ratio" # number - Damping of the angular softness.
---| "joint.weld.collide_connected" # boolean - Let the two connected bodies collide with each other.
---| "joint.wheel.local_anchor_a" # Vec2 - Anchor on body A, relative to its origin (px).
---| "joint.wheel.local_anchor_b" # Vec2 - Anchor on body B, relative to its origin (px).
---| "joint.wheel.local_axis_a" # Vec2 - Suspension direction, in body A's space.
---| "joint.wheel.enable_spring" # boolean - Springy suspension along the axis.
---| "joint.wheel.hertz" # number - Spring stiffness as an oscillation frequency (Hz); 0 = no spring.
---| "joint.wheel.damping_ratio" # number - Spring damping: 0 bounces forever, 1 settles without overshoot.
---| "joint.wheel.enable_limit" # boolean - Clamp the joint's travel to the lower / upper limits.
---| "joint.wheel.lower_translation" # number - Suspension's lowest travel (px; with the limit on).
---| "joint.wheel.upper_translation" # number - Suspension's highest travel (px; with the limit on).
---| "joint.wheel.enable_motor" # boolean - Drive the joint at Motor Speed, up to the maximum force / torque.
---| "joint.wheel.max_motor_torque" # number - Strongest twist the wheel motor applies (pixel-scale bodies are heavy).
---| "joint.wheel.motor_speed" # number - Wheel spin speed the motor drives (radians/s).
---| "joint.wheel.collide_connected" # boolean - Let the two connected bodies collide with each other.
---| "debug_color" # number[] - Colour of the line drawn between the anchors.

